# Check what the agent did with itertoolz - did it add peekn?
# Search for edit_file/write_file calls on itertoolz
for term in ["itertoolz", "peekn"]:
    res = await CONTEXT.search(term)
    print(f"\nSearch for '{term}': {len(res.get('items', []))} results")
    for r in res.get('items', [])[:10]:
        snippet = r['snippet']
        if 'write_file' in snippet or 'edit_file' in snippet or 'def peekn' in snippet.lower():
            print(f"  offset={r['offset']}: {snippet[:300]}")

# Check if original code had peekn defined
res = await CONTEXT.search("def peekn")
if res['items']:
    for r in res['items']:
        print(f"FOUND peekn definition at {r['offset']}: {r['snippet']}")
else:
    print("NO 'def peekn' found anywhere in context - function was never defined")

# Also check the initial state of itertoolz (before agent modifications)
